// OData access for tests, through clients generated by the SAP Cloud SDK (odata/clients, see
// `bun run odata:generate`). Specs that call SAP services import `test` and `expect` from here
// instead of '../sap-plugin': the SAP locators stay available, so one test can prepare data over
// the API, run the business flow in the UI and check the result over the API again.
import type { HttpDestination } from '@sap-cloud-sdk/connectivity';
import { test as base, expect } from './index';
import { gwsampleBasic } from '../odata/clients/GWSAMPLE_BASIC';

// With its default (de)serializers: Edm.Decimal as BigNumber, Edm.DateTime as Moment.
const createGwsample = () => gwsampleBasic();

/** Registers an undo step for data the test created. */
export type Cleanup = (label: string, undo: () => Promise<unknown>) => void;

export interface SapApiFixtures {
	/**
	 * The system the OData clients call: SAP_API_URL with SAP_API_USERNAME / SAP_API_PASSWORD
	 * (basic authentication) and optionally SAP_CLIENT. Pass it to every `.execute()`. Skips the
	 * test when it is not configured. Deliberately no fallback to SAP_URL: API tests write data,
	 * and a missing variable must not send them, or the UI user's password, to another system.
	 */
	sapApi: HttpDestination;
	/** Typed client for the SAP Gateway sample service GWSAMPLE_BASIC. */
	gwsample: ReturnType<typeof createGwsample>;
	/**
	 * Undo steps run after the test, newest first, also when the test failed. A failing undo step
	 * fails the test: data it leaves behind would break later runs.
	 */
	cleanup: Cleanup;
}

function sapApiDestination(): { destination?: HttpDestination; missing: string[] } {
	const { SAP_API_URL: url, SAP_API_USERNAME: username, SAP_API_PASSWORD: password } = process.env;
	const missing = [
		!url && 'SAP_API_URL',
		!username && 'SAP_API_USERNAME',
		!password && 'SAP_API_PASSWORD'
	].filter((name): name is string => !!name);
	if (!url || !username || !password) return { missing };
	return {
		missing,
		destination: {
			url,
			username,
			password,
			authentication: 'BasicAuthentication',
			sapClient: process.env.SAP_CLIENT || undefined
		}
	};
}

export const test = base.extend<SapApiFixtures>({
	// oxlint-disable-next-line no-empty-pattern -- Playwright requires the destructuring form
	sapApi: async ({}, use, testInfo) => {
		const { destination, missing } = sapApiDestination();
		testInfo.skip(!destination, `missing env: ${missing.join(', ')}`);
		await use(destination!);
	},
	// oxlint-disable-next-line no-empty-pattern -- Playwright requires the destructuring form
	gwsample: async ({}, use) => {
		await use(createGwsample());
	},
	// oxlint-disable-next-line no-empty-pattern -- Playwright requires the destructuring form
	cleanup: async ({}, use) => {
		const steps: { label: string; undo: () => Promise<unknown> }[] = [];
		// Newest first, so an order is deleted before the product it uses.
		await use((label, undo) => {
			steps.unshift({ label, undo });
		});
		const failures: unknown[] = [];
		for (const { label, undo } of steps) {
			try {
				await base.step(`cleanup: ${label}`, async () => {
					await undo();
				});
			} catch (error) {
				failures.push(error);
			}
		}
		if (failures.length > 0)
			throw new AggregateError(failures, `${failures.length} cleanup step(s) failed`);
	}
});

export { expect };
export type { Locator, Page } from './index';
